function mkRegistry(): {
	getAvailable(): { id: string; provider: string; api: string }[];
	find(p: string, id: string): { id: string; provider: string; api: string } | undefined;
	getApiKeyAndHeaders(m: { id: string; provider: string; api: string }): Promise<{
