	}>;
} {
	const haiku = { id: "claude-haiku-4-5", provider: "anthropic", api: "anthropic-messages" };
	return {
		getAvailable: () => [haiku],
		find: (p, id) => (p === haiku.provider && id === haiku.id ? haiku : undefined),
		getApiKeyAndHeaders: async () => ({ ok: true, apiKey: "fake" }),
	};
}

function mkComplete(text: string, opts: { latencyMs?: number } = {}): PiCompleteFn {
	return async (_model, _ctx, options) => {
		if (opts.latencyMs) {
			await new Promise((res, rej) => {
				const t = setTimeout(res, opts.latencyMs);
				options?.signal?.addEventListener("abort", () => {
					clearTimeout(t);
					const err = new Error("aborted");
					err.name = "AbortError";
					rej(err);
				});
			});
		}
		return {
			content: [{ type: "text", text }],
			usage: { input: 50, output: 30, cacheRead: 0, cacheWrite: 0, totalTokens: 80 },
			stopReason: "stop",
		};
	};
}

function mkHits(n: number): SearchHit[] {
	return Array.from({ length: n }, (_, i) => ({
		title: `Hit ${i + 1}`,
		permalink: `profile/h${i + 1}`,
		score: 0.9 - i * 0.05,
		matched_chunk: `snippet content ${i + 1}`,
		content: `body ${i + 1}`,
		file_path: `profile/h${i + 1}.md`,
	}));
}

