function asNumber(v: string | undefined, fallback: number): number {
	if (v === undefined) return fallback;
	const n = Number(v);
	return Number.isFinite(n) ? n : fallback;
}

function envNumber(name: string, fallback: number): number {
	return asNumber(process.env[name], fallback);
}

function asBool(v: string | undefined, fallback: boolean): boolean {
	if (v === undefined) return fallback;
	return /^(true|1|yes|on)$/i.test(v);
}

function stripWrappingQuotes(v: string | undefined): string | undefined {
	if (!v) return v;
	let out = v;
	while (
		out.length >= 2 &&
		((out.startsWith('"') && out.endsWith('"')) || (out.startsWith("'") && out.endsWith("'")))
	) {
		out = out.slice(1, -1);
	}
	return out;
}

