#!/usr/bin/env node
import { spawnSync } from "node:child_process";
import {
  copyFileSync,
  existsSync,
  readFileSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { auditPromptDump, promptHealthWarnings } from "../test/support/prompt-health-audit.mjs";

const dumpPath = process.env.PI_PROMPT_HEALTH_DUMP_PATH || "/tmp/bridge-dump.json";
const flagPath = process.env.PI_PROMPT_HEALTH_FLAG_PATH || "/tmp/dump-next-request";
const acceptedDumpPath = process.env.PI_PROMPT_HEALTH_ACCEPTED_DUMP || "/tmp/pi-prompt-health-live-dump.json";
const command = process.env.PI_PROMPT_HEALTH_COMMAND || "pi";
const model = process.env.PI_PROMPT_HEALTH_MODEL || "claude-bridge/claude-sonnet-4-6";
const expectedDumpModel = process.env.PI_PROMPT_HEALTH_EXPECT_MODEL || model.replace(/^.*\//, "");
const attempts = Number.parseInt(process.env.PI_PROMPT_HEALTH_ATTEMPTS || "3", 10);
const timeoutMs = Number.parseInt(process.env.PI_PROMPT_HEALTH_TIMEOUT_MS || "120000", 10);
const marker = `PI_PROMPT_HEALTH_${process.pid}_${Date.now()}`;
const prompt = [
  `Prompt health live smoke marker: ${marker}`,
  "Reply exactly: ok",
].join("\n");

const attemptSummaries = [];

for (let attempt = 1; attempt <= attempts; attempt += 1) {
  const startedAt = Date.now();
  writeFileSync(
    flagPath,
    JSON.stringify({ marker, model: expectedDumpModel, requireTools: true }),
    "utf8",
  );

  const result = spawnSync(
    command,
    ["--no-session", "--model", model, "--thinking", "off", "-p", prompt],
    { encoding: "utf8", timeout: timeoutMs },
  );

  const summary = {
    attempt,
    status: result.status,
    signal: result.signal,
    stdout: result.stdout?.trim().slice(0, 500) ?? "",
    stderr: result.stderr?.trim().slice(0, 500) ?? "",
  };

  if (result.error) {
    attemptSummaries.push({ ...summary, error: result.error.message });
    continue;
  }
  if (result.status !== 0) {
    attemptSummaries.push({ ...summary, error: "pi_command_failed" });
    continue;
  }
  if (!existsSync(dumpPath)) {
    attemptSummaries.push({ ...summary, error: "dump_missing" });
    continue;
  }

  const dumpStat = statSync(dumpPath);
  const dumpText = readFileSync(dumpPath, "utf8");
  if (dumpStat.mtimeMs < startedAt - 1000) {
    attemptSummaries.push({ ...summary, error: "dump_not_fresh", dumpMtimeMs: dumpStat.mtimeMs });
    continue;
  }
  if (!dumpText.includes(marker)) {
    attemptSummaries.push({ ...summary, error: "dump_captured_different_request", dumpBytes: dumpText.length });
    continue;
  }

  const dump = JSON.parse(dumpText);
  if (!String(dump.model || "").includes(expectedDumpModel)) {
    attemptSummaries.push({
      ...summary,
      error: "dump_model_mismatch",
      dumpModel: dump.model,
      expectedDumpModel,
    });
    continue;
  }
  if (!Array.isArray(dump.tools) || dump.tools.length === 0) {
    attemptSummaries.push({ ...summary, error: "dump_missing_tools" });
    continue;
  }
  const audit = auditPromptDump(dump);
  const warnings = promptHealthWarnings(audit);
  copyFileSync(dumpPath, acceptedDumpPath);

  const report = {
    ok: warnings.length === 0,
    marker,
    model,
    expectedDumpModel,
    attempt,
    acceptedDumpPath,
    audit,
    warnings,
  };

  if (warnings.length > 0) {
    console.error(JSON.stringify(report, null, 2));
    process.exit(1);
  }

  console.log(JSON.stringify(report, null, 2));
  process.exit(0);
}

console.error(JSON.stringify({
  ok: false,
  marker,
  model,
  expectedDumpModel,
  error: "no_matching_live_prompt_dump",
  attempts: attemptSummaries,
}, null, 2));
process.exit(1);

