function readFlag(name) {
  const index = process.argv.indexOf(name);
  return index === -1 ? null : process.argv[index + 1] ?? null;
}

function discoverExtensionIds(manifests) {
  const ids = new Set();
  const extensionsRoot = join(repoRoot, "extensions");

  if (existsSync(extensionsRoot)) {
    for (const entry of readdirSync(extensionsRoot, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      if (entry.name === "node_modules" || entry.name === "third-party") continue;
      if (existsSync(join(extensionsRoot, entry.name, "package.json"))) ids.add(entry.name);
    }
