  const expected = new Set(Object.keys(capabilityPackages));
  const packagesRoot = join(repoRoot, "packages");
  if (!existsSync(packagesRoot)) return [...expected].sort();

  for (const entry of readdirSync(packagesRoot, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    const packagePath = join(packagesRoot, entry.name, "package.json");
    if (!existsSync(packagePath)) continue;
    if (entry.name.startsWith("pi-") && !entry.name.startsWith("my-pi-")) expected.add(entry.name);
