/**
 * Load recall config from disk:
 *   - file at recallConfigPath() provides the persistent override
 *   - DREAM_ACTIVE_RECALL=1 forces enabled=true for explicit live opt-in
 *   - DREAM_ACTIVE_RECALL=0 forces enabled=false as a kill switch
 *   - missing file → DEFAULT_RECALL_CONFIG
 */
export async function loadRecallConfig(): Promise<RecallConfig> {
	const path = recallConfigPath();
	let parsed: Record<string, string> = {};
	if (existsSync(path)) {
		try {
			parsed = parseFlatToml(await readFile(path, "utf8"));
		} catch {
			// fall through to defaults
		}
	}
	const cfg: RecallConfig = {
		enabled: asBool(parsed.enabled, DEFAULT_RECALL_CONFIG.enabled),
		model_alias: ((parsed.model_alias as RecallConfig["model_alias"]) ??
			DEFAULT_RECALL_CONFIG.model_alias),
		budget_ms: asNumber(parsed.budget_ms, DEFAULT_RECALL_CONFIG.budget_ms),
		ceiling_ms: asNumber(parsed.ceiling_ms, DEFAULT_RECALL_CONFIG.ceiling_ms),
		breaker_threshold: asNumber(
			parsed.breaker_threshold,
			DEFAULT_RECALL_CONFIG.breaker_threshold,
		),
		breaker_cooldown_ms: asNumber(
			parsed.breaker_cooldown_ms,
			DEFAULT_RECALL_CONFIG.breaker_cooldown_ms,
		),
		max_hits: asNumber(parsed.max_hits, DEFAULT_RECALL_CONFIG.max_hits),
		model_override: parsed.model_override ?? undefined,
		show_ui: asBool(parsed.show_ui, DEFAULT_RECALL_CONFIG.show_ui),
		qmd_mode: ((stripWrappingQuotes(parsed.qmd_mode) as RecallConfig["qmd_mode"]) ??
			DEFAULT_RECALL_CONFIG.qmd_mode),
		context_turns: asNumber(parsed.context_turns, DEFAULT_RECALL_CONFIG.context_turns),
		prompt_variant: ((stripWrappingQuotes(parsed.prompt_variant) as RecallConfig["prompt_variant"]) ??
			DEFAULT_RECALL_CONFIG.prompt_variant),
		min_score: asNumber(parsed.min_score, DEFAULT_RECALL_CONFIG.min_score),
		candidate_limit: asNumber(parsed.candidate_limit, DEFAULT_RECALL_CONFIG.candidate_limit),
		auto_none_threshold: asNumber(parsed.auto_none_threshold, DEFAULT_RECALL_CONFIG.auto_none_threshold),
		min_prompt_length: asNumber(parsed.min_prompt_length, DEFAULT_RECALL_CONFIG.min_prompt_length),
		qmd_http_port: asNumber(parsed.qmd_http_port, DEFAULT_RECALL_CONFIG.qmd_http_port),
	};
	if (process.env.DREAM_ACTIVE_RECALL === "1") cfg.enabled = true;
	if (process.env.DREAM_ACTIVE_RECALL === "0") cfg.enabled = false;
	// Env overrides — autoresearch knobs (Phase 0c + 0d). Each is opt-in;
	// missing env vars leave the toml/default value in place.
	if (process.env.RECALL_MAX_HITS) cfg.max_hits = envNumber("RECALL_MAX_HITS", cfg.max_hits);
	if (process.env.RECALL_BUDGET_MS) cfg.budget_ms = envNumber("RECALL_BUDGET_MS", cfg.budget_ms);
	if (process.env.RECALL_MODEL_ALIAS) {
		cfg.model_alias = process.env.RECALL_MODEL_ALIAS as RecallConfig["model_alias"];
	}
	if (process.env.RECALL_MODEL_OVERRIDE) cfg.model_override = process.env.RECALL_MODEL_OVERRIDE;
	if (process.env.RECALL_QMD_MODE) {
		cfg.qmd_mode = process.env.RECALL_QMD_MODE as RecallConfig["qmd_mode"];
	}
	if (process.env.RECALL_CONTEXT_TURNS) cfg.context_turns = envNumber("RECALL_CONTEXT_TURNS", cfg.context_turns);
	if (process.env.RECALL_PROMPT_VARIANT) {
		cfg.prompt_variant = process.env.RECALL_PROMPT_VARIANT as RecallConfig["prompt_variant"];
	}
	if (process.env.RECALL_MIN_SCORE) cfg.min_score = envNumber("RECALL_MIN_SCORE", cfg.min_score);
	if (process.env.RECALL_CANDIDATE_LIMIT) {
		cfg.candidate_limit = envNumber("RECALL_CANDIDATE_LIMIT", cfg.candidate_limit);
