	// (writes ~/.dream-memory/last-dream.json), surface a one-line notify the
	// next time the user submits a prompt. Initialised lazily on first turn so
	// we don't notify about dreams that ran before this session started.
	let lastSeenDreamAt: number | null = null;
	async function notifyOnNewDream(ctx: { ui?: ExtensionContext["ui"] }): Promise<void> {
		try {
			const { readLastDreamSummary } = await import("./dream/runner.ts");
			const last = await readLastDreamSummary();
			if (!last) return;
			if (lastSeenDreamAt === null) {
				lastSeenDreamAt = last.at;
				return;
			}
			if (last.at <= lastSeenDreamAt) return;
			lastSeenDreamAt = last.at;
			if (!ctx.ui) return;
			if (!(await claimDreamNotification(last))) return;
			const t = ctx.ui.theme;
			const dim = (s: string) => t ? t.fg("dim", s) : s;
			// UI-only append notification. Keep dream summaries out of system prompt,
			// transcript custom messages, and cached prefix.
			ctx.ui.notify(`🌙 dream: ${dim(formatDreamNotificationSummary(last))}`);
		} catch {
			// best-effort; never block a turn on notify failure
		}
	}

	async function claimDreamNotification(last: { at: number; runId?: string; committedSha?: string }): Promise<boolean> {
		const { mkdir, open } = await import("node:fs/promises");
		const { join } = await import("node:path");
		const key = dreamNotificationKey(last);
		const dir = join(eventsRoot(), "dream-notifications");
		await mkdir(dir, { recursive: true });
		let fh: Awaited<ReturnType<typeof open>> | undefined;
		try {
			fh = await open(join(dir, `${key}.json`), "wx");
			await fh.writeFile(JSON.stringify({ at: last.at, runId: last.runId, committedSha: last.committedSha, notifiedAt: Date.now() }) + "\n");
			return true;
		} catch (err) {
			if ((err as NodeJS.ErrnoException).code === "EEXIST") return false;
			throw err;
		} finally {
			await fh?.close().catch(() => undefined);
		}
	}

	function dreamNotificationKey(last: { at: number; runId?: string; committedSha?: string }): string {
		return String(last.runId ?? last.committedSha ?? last.at).replace(/[^a-zA-Z0-9_.-]/g, "_");
	}

	function isActiveRecallMessage(message: ContextEvent["messages"][number]): boolean {
		return message.role === "custom" && message.customType === ACTIVE_RECALL_CUSTOM_TYPE;
	}

	// CACHE CRITICAL: context is the only model-facing delivery path for active
	// recall. It replaces the per-call message list, strips stale
	// dream-memory.active-recall custom messages from durable history, and
	// appends only the current settled recall at the tail. before_agent_start
	// must never return per-turn recall
	// messages or dynamic systemPrompt content; those mutate cached prompt
	// prefixes instead of appending after Pi's stable prompt/tools boundary.
	pi.on("context", (event: ContextEvent, ctx): void | { messages?: typeof event.messages } => {
		if (pendingRecall?.settled && lastCfg) {
			// Fire-and-forget footer update — readBreakerState is a fast file read.
			const cfg = lastCfg;
			void readBreakerState().catch(() => undefined).then(breaker => {
				try { if (breaker) updateFooter(ctx, cfg.enabled, cfg.show_ui, isBreakerOpen(breaker, cfg, Date.now())); } catch {}
			});
		}
		const cacheStableMessages = event.messages.filter((message) => !isActiveRecallMessage(message));
		const showUi = pendingRecall?.showUi ?? false;
		const active = takeSettledRecall();
		if (!active) {
			return cacheStableMessages.length === event.messages.length ? undefined : { messages: cacheStableMessages };
		}
		void recordActiveRecallInjected(ctx, active, "context");
		if (showUi) {
			ctx.ui?.notify(`🧠 recalled ${active.message.details.hits} ${active.message.details.hits === 1 ? "memory" : "memories"}`);
		}
		const injected = {
			role: "custom" as const,
			customType: ACTIVE_RECALL_CUSTOM_TYPE,
			content: active.message.content,
			display: showUi,
			details: active.message.details,
			timestamp: Date.now(),
		};
		return { messages: [...cacheStableMessages, injected] };
	});

	function fireRecallAsync(
		recallOpts: Parameters<typeof runActiveRecall>[0],
