export async function appendEvent(input: AppendEventInput): Promise<Event | null> {
	try {
		await ensureDirs();
		const payload = input.payload ?? {};
		const { value: redactedPayload, hits } = redact(payload);
		const event: Event = {
			event_id: ulid(),
			session_id: input.sessionId,
			client: input.client,
			cwd: input.cwd,
			project_slug: input.projectSlug,
			ts: new Date().toISOString(),
			event_type: input.eventType,
			payload: redactedPayload as Record<string, unknown>,
			payload_hash: createHash("sha256").update(canonicalJSON(redactedPayload)).digest("hex"),
			redaction_hits: hits,
		};
		const line = JSON.stringify(event) + "\n";
		const path = join(eventsDir(), `${input.sessionId}.jsonl`);
		const handle = await open(path, "a");
		try {
			await handle.appendFile(line);
			await handle.datasync();
		} finally {
			await handle.close();
		}
		return event;
	} catch (err) {
		// Never throw past appendEvent — hooks must not block the harness.
		console.error("[dream-memory] appendEvent failed:", err);
		return null;
	}
}

